'use strict';
(()=>{
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const runtime=window.RUNTIME||{}, demo=runtime.demo===true||location.protocol==='file:', adminEntry=runtime.admin===true;
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}};
const put=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{throw Error('Browser storage is full or unavailable. Remove a photo or enable local storage. / Хранилище браузера недоступно.')}};
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
let lang=read('mr-language','en');if(!['en','ru'].includes(lang))lang='en';
let data=demo?read('mr-demo-platform-v1',null):null; if(!data?.products||!data.settings)data={...structuredClone(window.SEED),inquiries:[]};
let saved=read('mr-selection',[]);if(!Array.isArray(saved))saved=[];
let session=null, menu=false, heroIndex=0, filter='all', tagFilter='', search='', sort='curated', adminSearch='', editor=null, editing=false, lastSuccess=null, requestBusy=false, loadError='', toastTimer;
let flags={inquiriesEnabled:demo,channels:[],privacy:{controller:'',contact:'',retention:180},publicUrl:runtime.publicUrl||'/'};
const tr=(en,ru)=>lang==='en'?en:ru;const local=(o,k)=>o[k+(lang==='en'?'En':'Ru')]||o[k+'En']||o[k+'Ru']||'';
const money=n=>n===null||n===undefined?tr('Price on request','Цена по запросу'):new Intl.NumberFormat(lang==='en'?'en-IE':'ru-RU',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
const labels={on_request:()=>tr('Availability on request','Наличие уточняется'),available:()=>tr('Available','В наличии'),reserved:()=>tr('Reserved','Забронировано'),sold:()=>tr('Sold','Продано')};
const cat=c=>({sculpture:tr('Sculpture','Скульптура'),painting:tr('Painting','Живопись'),other:tr('Other works','Другие работы')}[c]||c);
const icon=(name='arrow')=>{const shapes={arrow:'<path d="M5 19 19 5M5 5h14v14"/>',right:'<path d="m9 5 7 7-7 7"/>',left:'<path d="m15 5-7 7 7 7"/>',down:'<path d="M12 4v16m-6-6 6 6 6-6"/>',bag:'<path d="M5 7h14l1 14H4L5 7Zm3 0V5a4 4 0 0 1 8 0v2"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 8h16M4 16h16"/>',zoom:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6M7 10h6m-3-3v6"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1"/><path d="m3 17 5-5 4 3 4-6 5 8"/>',edit:'<path d="m16 3 5 5-12 12-6 1 1-6L16 3Zm-2 2 5 5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',grid:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',send:'<path d="m3 10 18-7-7 18-3-8-8-3ZM11 13 21 3"/>',export:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${shapes[name]||shapes.arrow}</svg>`};
const routeHref=p=>demo?'#'+p:p;const link=(p,text,cls='')=>`<a data-route href="${e(routeHref(p))}" class="${cls}">${text}</a>`;
const path=()=>demo?(location.hash.slice(1)|| (adminEntry?'/admin':'/')):location.pathname+location.search;
const go=p=>{menu=false;if(demo){if(path()===p){render();window.scrollTo(0,0)}else location.hash=p}else{history.pushState({},'',p);render();window.scrollTo(0,0)}};
const notice=(text,type='info')=>`<div class="notice ${type}">${text}</div>`;
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600)}
const asset=u=>window.ASSETS?.[u]||u;
function safeImage(u){if(typeof u!=='string')return '';if(/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(u)&&demo)return u;if(/^\/(assets|uploads)\/[a-zA-Z0-9_.-]+\.(jpg|jpeg|png|webp)$/.test(u))return u;try{const x=new URL(u);if(x.protocol==='https:'&&['www.artevistas.eu','artevistas.eu'].includes(x.hostname))return x.href}catch{}return ''}
const safeExternal=u=>{try{const x=new URL(u);return x.protocol==='https:'&&!x.username&&!x.password?x.href:'#'}catch{return '#'}};
function media(u,title,{cls='',eager=false,sold=false}={}){return `<div class="media ${cls}"><div class="fallback">${icon('image')}<span class="fallback-title">${e(title)}</span><span class="small">${tr('Original photo · Artevistas','Оригинальное фото · Artevistas')}<br>${tr('An internet connection is needed.','Для загрузки нужен интернет.')}</span></div><img src="${e(asset(safeImage(u)))}" alt="${e(title)}" loading="${eager?'eager':'lazy'}" decoding="async" ${eager?'fetchpriority="high"':''}>${sold?`<div class="sold-glass">${tr('SOLD','ПРОДАНО')}<small>${tr('ARCHIVE WORK','АРХИВНАЯ РАБОТА')}</small></div>`:''}</div>`}
function bindImages(root=document){$$('.media img,.thumb img',root).forEach(img=>{const ok=()=>{img.parentElement.classList.add('loaded');img.parentElement.classList.remove('failed')};const bad=()=>{img.parentElement.classList.add('failed');img.parentElement.classList.remove('loaded')};img.addEventListener('load',ok);img.addEventListener('error',bad);if(img.complete)(img.naturalWidth?ok:bad)()})}
async function api(p,method='GET',body){if(demo)return demoApi(p,method,body);const headers={'Content-Type':'application/json'};if(session?.csrf)headers['X-CSRF-Token']=session.csrf;const res=await fetch(p,{method,headers,credentials:'same-origin',body:body?JSON.stringify(body):undefined});let out={};try{out=await res.json()}catch{}if(!res.ok){if(res.status===401)session=null;throw Error(out.error||tr('The request failed. Please try again.','Не удалось выполнить запрос. Попробуйте снова.'))}return out}
function persist(next){put('mr-demo-platform-v1',next);data=next}
async function demoApi(p,method,body){let next=structuredClone(data);if(p==='/api/admin/state')return {...data};if(p==='/api/admin/upload')return {url:body.image};if(p==='/api/admin/products'&&method==='POST'){if(next.products.some(x=>x.id===body.id))throw Error('This ID already exists. / Такой ID уже есть.');next.products.unshift({...body,version:1});persist(next);return body}if(p.startsWith('/api/admin/products/')){const id=p.split('/').pop(),i=next.products.findIndex(x=>x.id===id);if(i<0)throw Error('Work not found');if(method==='DELETE')next.products.splice(i,1);else next.products[i]={...body,id,version:(next.products[i].version||0)+1};persist(next);return {ok:true}}if(p==='/api/admin/settings'){next.settings={...next.settings,...body};persist(next);return next.settings}if(p==='/api/inquiries'){const existing=next.inquiries.find(x=>x.submissionId===body.submissionId);if(existing)return existing;const items=body.productIds.map(id=>next.products.find(p=>p.id===id));if(items.some(x=>!x?.published||['sold','reserved'].includes(x.availability)))throw Error(tr('A selected work is no longer available. Refresh your selection.','Одна из работ больше недоступна. Обновите список.'));const q={...body,id:uid(),reference:'DEMO-'+Date.now().toString(36).slice(-6).toUpperCase(),items:items.map(x=>({id:x.id,title:x.title,price:x.price,sku:x.sku})),createdAt:new Date().toISOString(),status:'new',deliveries:[]};next.inquiries.unshift(q);persist(next);return q}if(p.startsWith('/api/admin/inquiries/')){const id=p.split('/')[4];if(method==='DELETE')next.inquiries=next.inquiries.filter(x=>x.id!==id);else{const q=next.inquiries.find(x=>x.id===id);if(q)q.status=body.status}persist(next);return {ok:true}}throw Error('Unavailable in the local preview. / Доступно только в серверной версии.')}
const published=()=>data.products.filter(p=>p.published);const activeSaved=()=>saved.map(id=>published().find(p=>p.id===id)).filter(Boolean);
function header(){const p=path();return `<header class="header"><div class="wrap header-inner">${link('/','MARK ROX<i aria-hidden="true"></i>','brand')}<nav class="nav" aria-label="${tr('Main navigation','Основная навигация')}">${[['/works',tr('Works','Работы')],['/works?type=sculpture','ARTonaut'],['/artist',tr('The artist','Художник')],['/contact',tr('Contact','Контакт')]].map(([u,t])=>link(u,t,p===u?'active':'')).join('')}</nav><div class="tools"><button data-action="language" class="lang" aria-label="${tr('Switch to Russian','Переключить на английский')}">${lang.toUpperCase()}<span class="muted">/ ${lang==='en'?'RU':'EN'}</span></button>${link('/inquiry',icon('bag')+`<span class="bag-label">${tr('Selection','Выбрано')}</span><b>${activeSaved().length}</b>`,'bag')}<button class="icon menu-btn" data-action="menu" aria-label="${tr('Menu','Меню')}" aria-expanded="${menu}">${icon(menu?'close':'menu')}</button></div></div>${menu?`<nav class="mobile-nav">${[['/works',tr('Works','Работы')],['/works?type=sculpture','ARTonaut'],['/artist',tr('The artist','Художник')],['/contact',tr('Contact','Контакт')]].map(([u,t])=>link(u,t)).join('')}</nav>`:''}</header>${loadError?`<div class="runtime-error">${e(loadError)}</div>`:''}`}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-top"><div>${link('/','MARK ROX<i aria-hidden="true"></i>','brand')}<p>${tr('A different point of view.','Другой взгляд на привычное.')}</p></div><nav class="footer-nav">${link('/works',tr('Works','Работы'))}${link('/artist',tr('The artist','Художник'))}${link('/contact',tr('Get in touch','Связаться'))}${data.settings.instagram?`<a href="${e(safeExternal(data.settings.instagram))}" target="_blank" rel="noopener noreferrer">Instagram ↗</a>`:''}</nav></div><div class="wordmark" aria-hidden="true">MARK ROX</div><div class="footer-bottom"><span>© ${new Date().getFullYear()} ${e(data.settings.name)}. ${tr('Artwork rights reserved.','Права на работы защищены.')}</span>${link('/privacy',tr('Privacy & enquiries','Данные и заявки'))}<a href="${e(data.settings.source)}" target="_blank" rel="noopener noreferrer">Artevistas Gallery ↗</a></div>${demo?`<p class="image-notice">${tr('Design preview · Original photographs load from Artevistas. Enquiries in this preview are local only.','Демонстрационная версия · Оригинальные фотографии загружаются из Artevistas. Заявки в этом просмотре сохраняются только локально.')}</p>`:''}</div></footer>`}
function workCard(p){return `<article class="work">${link('/work/'+p.id,media(p.images[0],p.title,{sold:p.availability==='sold'})+(p.availability!=='sold'?`<span class="sr">${e(labels[p.availability]?.())}</span>`:''),'media-link')}<div class="work-head"><h3>${link('/work/'+p.id,e(p.title))}</h3>${!['sold','reserved'].includes(p.availability)?`<button class="icon ${saved.includes(p.id)?'selected':''}" data-action="save" data-id="${e(p.id)}" aria-label="${e(tr('Select ','Выбрать ')+p.title)}" aria-pressed="${saved.includes(p.id)}">${icon(saved.includes(p.id)?'check':'plus')}</button>`:''}</div><p class="meta">${cat(p.category)}${p.year?' · '+p.year:''}</p><p class="price">${p.availability==='sold'?tr('Archive work','Архивная работа'):e(money(p.price))}</p></article>`}
function faq(){const pairs=[[tr('How do I acquire a work?','Как приобрести работу?'),tr('Open an artwork, add it to your selection and send an enquiry. Availability, final price and delivery are agreed before any payment. The website does not charge your card.','Откройте карточку, добавьте работу в список и отправьте запрос. Наличие, окончательная цена и доставка согласуются до оплаты. Сайт не списывает деньги с карты.')],[tr('Can I see the details?','Можно рассмотреть детали?'),tr('Each artwork has a gallery of original photographs. Open an image, move between angles and zoom in. Ask for additional photographs in your enquiry.','В каждой карточке есть галерея оригинальных фотографий. Откройте снимок, переключайтесь между ракурсами и увеличивайте изображение. Дополнительные фотографии можно запросить в заявке.')],[tr('What about shipping?','Как устроена доставка?'),tr('Share your destination city in the enquiry. Packaging, shipping cost, insurance and any customs charges need individual confirmation. No delivery charges are included automatically.','Укажите город назначения в заявке. Упаковка, стоимость перевозки, страхование и возможные пошлины согласуются отдельно. Доставка не включается автоматически.')],[tr('Is a sold work still available?','Можно купить проданную работу?'),tr('No. Sold works remain in the archive and cannot be added to a purchase enquiry. You can discuss a different work or a new project through the contact form.','Нет. Проданные работы остаются в архиве, но не добавляются в заявку на покупку. Через форму связи можно обсудить другую работу или новый проект.')]];return `<section class="collector section"><div class="wrap collector-grid"><div><p class="eyebrow">${tr('FOR COLLECTORS','КОЛЛЕКЦИОНЕРАМ')}</p><h2>${tr('Good art.<br>Clear answers.','Искусство.<br>Без лишних вопросов.')}</h2></div><div class="faq">${pairs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></div></section>`}
const cta=()=>`<section class="wrap cta"><div><p class="eyebrow">${tr('ACQUISITIONS / PROJECTS / COLLABORATIONS','ПРИОБРЕТЕНИЕ / ПРОЕКТЫ / СОТРУДНИЧЕСТВО')}</p><h2>${tr('Let’s make it real.','Давайте воплотим идею.')}</h2></div>${link('/contact',icon('arrow')+`<span class="sr">${tr('Contact the studio','Связаться')}</span>`,'icon')}</section>`;
function home(){const s=data.settings,heroList=[published().find(p=>p.id===s.heroId),...published().filter(p=>p.id!==s.heroId&&p.featured)].filter(Boolean).slice(0,3),p=heroList[heroIndex%Math.max(1,heroList.length)];return `<main id="main"><section class="wrap hero"><div class="hero-kicker"><p class="eyebrow"><span class="dot"></span>${tr('MARK ROX / ARTIST & CREATOR','MARK ROX / ХУДОЖНИК')}</p><p class="eyebrow muted">${tr('A DIFFERENT POINT OF VIEW','ДРУГОЙ ВЗГЛЯД')}</p></div><div class="hero-grid"><div class="hero-copy"><h1>${e(local(s,'headline'))}</h1><p class="hero-desc">${e(local(s,'intro'))}</p><div class="actions">${link('/works',tr('Explore works','Смотреть работы')+icon('arrow'),'btn')}${link('/artist',tr('Meet the artist','О художнике'),'textlink')}</div><p class="signature">${tr('Street roots. No boundaries.','Уличные корни. Без границ.')}<br>${tr('Creating since 2008.','В искусстве с 2008 года.')}</p></div>${p?`<div class="hero-frame">${link('/work/'+p.id,media(p.images[0],p.title,{eager:true,sold:p.availability==='sold'}),'media-link')}<div class="hero-caption"><div><strong>${e(p.title)}</strong><p>${cat(p.category)} · ${p.year||''}</p></div><div class="hero-controls"><span aria-live="polite">${String(heroIndex%heroList.length+1).padStart(2,'0')} / ${String(heroList.length).padStart(2,'0')}</span><button class="icon" data-action="hero-next" aria-label="${tr('Next featured work','Следующая работа')}">${icon('right')}</button></div></div></div>`:''}</div><div class="hero-bottom"><a href="${e(s.source)}" target="_blank" rel="noopener noreferrer">${tr('Represented by Artevistas Gallery, Barcelona','Представлен в Artevistas Gallery, Барселона')} ↗</a><span>SCULPTURE / PAINTING / STREET ART</span>${link('/works',tr('Discover','Смотреть')+icon('down'))}</div></section><section class="wrap section rule"><div class="section-head"><div><p class="eyebrow">01 / ${tr('THE COLLECTION','КОЛЛЕКЦИЯ')}</p><h2>${tr('Selected works','Избранные работы')}<sup class="num">${String(published().length).padStart(2,'0')}</sup></h2></div>${link('/works',tr('View all works','Все работы')+icon('arrow'),'textlink')}</div><div class="works">${published().filter(p=>p.featured).slice(0,6).map(workCard).join('')}</div></section><section class="manifesto"><div class="wrap manifesto-grid"><p class="eyebrow">02 / ARTonaut</p><div><h2>${tr('Not just an object.\nA whole new orbit.','Не просто объект.\nСвоя орбита.')}</h2><p>${tr('From the energy of the street to a sculptural form. Explore the ARTonaut collection, one detail at a time.','От энергии улиц к скульптурной форме. Откройте коллекцию ARTonaut, рассматривая каждую деталь.')}</p>${link('/works?type=sculpture',tr('Explore ARTonaut','Коллекция ARTonaut')+icon('arrow'),'textlink')}</div></div></section><section class="wrap section about"><figure>${media(s.portrait,'Mark Rox',{cls:'portrait'})}<figcaption class="caption"><span>Mark Rox</span><span>${tr('Photo: Artevistas Gallery','Фото: Artevistas Gallery')}</span></figcaption></figure><div><p class="eyebrow">03 / ${tr('BEHIND THE WORK','ЗА РАБОТАМИ')}</p><h2>${tr('From the street.<br>Beyond the frame.','С улицы.<br>За пределы рамы.')}</h2><p>${e(local(s,'bio'))}</p>${link('/artist',tr('The story of Mark Rox','История Mark Rox')+icon('arrow'),'textlink')}</div></section>${faq()}${cta()}</main>`}
function catalogue(params){const requested=params.get('type');if(requested&&['sculpture','painting','sold'].includes(requested))filter=requested;let ps=published();const tabs=[['all',tr('All works','Все работы')],['sculpture',tr('Sculptures','Скульптуры')],['painting',tr('Paintings','Живопись')],['sold',tr('Archive','Архив')]];const count=f=>ps.filter(p=>f==='all'||(f==='sold'?p.availability==='sold':p.category===f)).length;const tags=[...new Set(ps.flatMap(p=>p.tags||[]))].slice(0,12);let found=ps.filter(p=>(filter==='all'||(filter==='sold'?p.availability==='sold':p.category===filter))&&(!tagFilter||(p.tags||[]).includes(tagFilter))&&[p.title,cat(p.category),...(p.tags||[])].join(' ').toLowerCase().includes(search.toLowerCase()));if(sort==='price-asc')found.sort((a,b)=>(a.price??Infinity)-(b.price??Infinity));if(sort==='price-desc')found.sort((a,b)=>(b.price??-Infinity)-(a.price??-Infinity));if(sort==='newest')found.sort((a,b)=>(b.year||0)-(a.year||0));return `<main id="main" class="wrap catalogue"><div class="page-head"><p class="eyebrow">THE ART OF MARK ROX</p><h1>${tr('The collection.','Коллекция.')}<sup class="num">${String(ps.length).padStart(2,'0')}</sup></h1><p>${tr('Paintings, sculptures, a different point of view. Find the work that stays with you.','Живопись, скульптура, другой взгляд на привычное. Найдите работу, которая останется с вами.')}</p></div><div class="filters"><div class="tabs" aria-label="${tr('Categories','Категории')}">${tabs.map(([v,n])=>`<button class="tab ${filter===v?'active':''}" data-action="filter" data-filter="${v}" aria-pressed="${filter===v}">${n}<sup>${count(v)}</sup></button>`).join('')}</div><div class="filter-right"><label><span class="sr">${tr('Search works','Поиск работ')}</span><input class="search" id="catalogue-search" placeholder="${tr('Search works or tags','Название или тег')}" value="${e(search)}" type="search"></label><label><span class="sr">${tr('Sort','Сортировка')}</span><select id="catalogue-sort">${[['curated',tr('Curated selection','Порядок галереи')],['newest',tr('Newest first','Сначала новые')],['price-asc',tr('Price: low to high','Цена: по возрастанию')],['price-desc',tr('Price: high to low','Цена: по убыванию')]].map(([v,n])=>`<option value="${v}" ${v===sort?'selected':''}>${n}</option>`).join('')}</select></label></div></div><div class="tag-row">${tags.map(t=>`<button class="tag ${tagFilter===t?'active':''}" data-action="tag" data-tag="${e(t)}" aria-pressed="${tagFilter===t}">${e(t)}</button>`).join('')}</div><div id="catalogue-results">${found.length?`<div class="works">${found.map(workCard).join('')}</div>`:empty(tr('No works found.','Работы не найдены.'),tr('Try another category, tag or title.','Попробуйте другую категорию, тег или название.'),`<button class="btn secondary" data-action="clear-filters">${tr('Clear filters','Сбросить фильтры')}</button>`)}</div></main>`}
const empty=(title,text,button='')=>`<div class="empty"><h2>${title}</h2><p>${text}</p>${button}</div>`;
function productPage(id){const p=published().find(x=>x.id===id);if(!p)return notFound();const disabled=['sold','reserved'].includes(p.availability);return `<main id="main" class="wrap"><div class="crumb">${link('/',tr('Home','Главная'))}<span>/</span>${link('/works',tr('Works','Работы'))}<span>/</span><span>${e(p.title)}</span></div><div class="product"><div><button class="main-photo" data-action="lightbox" data-id="${e(p.id)}" aria-label="${tr('Open image gallery','Открыть галерею')}">${media(p.images[0],p.title,{eager:true,sold:p.availability==='sold'})}<span class="sr">${tr('Zoom photograph','Увеличить фото')}</span></button><div class="thumbs">${p.images.map((u,i)=>`<button class="thumb ${i===0?'active':''}" data-action="thumbnail" data-index="${i}" data-id="${e(p.id)}" aria-label="${tr('View','Ракурс')} ${i+1}" aria-pressed="${i===0}"><span>${i+1}</span><img src="${e(asset(safeImage(u)))}" alt="${e(p.title)} — ${i+1}"></button>`).join('')}</div><p class="small muted" style="margin-top:16px">${tr('Click an image to open. Zoom in to explore the details.','Нажмите на фото, чтобы открыть его и рассмотреть детали.')}</p></div><div class="product-info"><p class="eyebrow">MARK ROX / ${cat(p.category).toUpperCase()}</p><h1>${e(p.title)}</h1><p class="product-price">${p.availability==='sold'?tr('Sold · archive','Продано · архив'):e(money(p.price))}</p><p class="availability"><span class="dot"></span>${e(labels[p.availability]?.())}</p><p class="description">${e(local(p,'description'))}</p><dl class="specs">${[[tr('Medium','Материал'),local(p,'medium')],[tr('Dimensions','Размер'),p.dimensions],[tr('Year','Год'),p.year],[tr('Reference','Артикул'),p.sku]].filter(x=>x[1]).map(([a,b])=>`<div><dt>${a}</dt><dd>${e(b)}</dd></div>`).join('')}</dl><div class="actions">${disabled?link('/contact?subject='+encodeURIComponent(p.title),tr('Discuss a similar work','Обсудить другую работу')+icon('arrow'),'btn'):`<button class="btn" data-action="enquire" data-id="${e(p.id)}">${tr('Enquire about this work','Запросить работу')}${icon('arrow')}</button><button class="btn secondary ${saved.includes(p.id)?'selected':''}" data-action="save" data-id="${e(p.id)}">${icon(saved.includes(p.id)?'check':'plus')}${saved.includes(p.id)?tr('Selected','В списке'):tr('Select','В список')}</button>`}</div><p class="product-note">${tr('An enquiry, not a payment. Availability, final price and delivery are confirmed personally.','Это запрос, не оплата. Наличие, окончательная цена и доставка подтверждаются при ответе.')}</p><div class="product-tags">${(p.tags||[]).map(t=>`<span>${e(t)}</span>`).join('')}</div>${p.sourceUrl?`<details class="source"><summary>${tr('Artwork information & source','Информация о работе и источник')}</summary><p>${tr('Specifications and listed prices are from Artevistas Gallery, reviewed 8 September 2026. The source pages can change. Sold status follows the individual artwork page where listings conflict. Please confirm availability before purchase.','Характеристики и цены — из Artevistas Gallery, проверены 8 сентября 2026. Источники могут меняться. При расхождении статусов использована отдельная карточка работы. Наличие перед покупкой нужно подтвердить.')}</p><a href="${e(safeExternal(p.sourceUrl))}" target="_blank" rel="noopener noreferrer">Artevistas Gallery ↗</a></details>`:''}</div></div><section class="section rule"><div class="section-head"><h2>${tr('Keep exploring.','Продолжить знакомство.')}</h2>${link('/works',tr('All works','Все работы')+icon('arrow'),'textlink')}</div><div class="works">${published().filter(x=>x.id!==id).slice(0,3).map(workCard).join('')}</div></section></main>`}
function artist(){const s=data.settings;return `<main id="main"><div class="wrap page-head"><p class="eyebrow">BEHIND THE WORK</p><h1>${tr('A different<br>point of view.','Другой взгляд<br>на привычное.')}</h1></div><section class="wrap about section" style="padding-top:16px"><figure>${media(s.portrait,'Mark Rox',{cls:'portrait',eager:true})}<figcaption class="caption">Mark Rox<span>Artevistas Gallery</span></figcaption></figure><div><p class="eyebrow">${tr('ARTIST / CREATOR / EXPLORER','ХУДОЖНИК / СОЗДАТЕЛЬ / ИССЛЕДОВАТЕЛЬ')}</p><h2>${e(s.name)}</h2><p>${e(local(s,'bio'))}</p><p>${e(local(s,'more'))}</p><a class="textlink" href="${e(s.source)}" target="_blank" rel="noopener noreferrer">${tr('Artist profile at Artevistas','Профиль в Artevistas')} ${icon('arrow')}</a></div></section><section class="wrap section rule"><div class="artist-text"><h2>${tr('One artist. Many dimensions.','Один художник. Много измерений.')}</h2><p>${tr('A practice spanning urban spaces, painted surfaces and sculptural objects. The website brings these different dimensions together without losing sight of the work itself.','Практика, объединяющая городские пространства, живопись и скульптурные объекты. Здесь разные направления собраны вместе, но в центре внимания всегда остаётся сама работа.')}</p></div><div class="practice">${[['01',tr('Street art','Стрит-арт'),tr('The city as a space for experimentation. Graffiti and 3D illusions form part of the artist’s visual language.','Город как пространство эксперимента. Граффити и 3D-иллюзии — часть визуального языка художника.')],['02',tr('Painting','Живопись'),tr('Canvas, colour and layered perception. Explore paintings documented by Artevistas Gallery.','Холст, цвет и многослойное восприятие. Живопись, представленная в каталоге Artevistas Gallery.')],['03','ARTonaut',tr('A sculptural collection. Explore the acrylic-cement objects from multiple angles.','Коллекция скульптур. Объекты из акрилового цемента, которые можно рассмотреть с разных ракурсов.')]].map(([n,t,d])=>`<div><p class="eyebrow">${n}</p><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></section>${cta()}</main>`}
function field(name,label,value='',options={}){const {type='text',wide=false,required=false,placeholder='',readonly=false,max=300}=options;return `<div class="field ${wide?'wide':''}"><label for="f-${e(name)}">${label}${required?' *':''}</label>${type==='textarea'?`<textarea id="f-${e(name)}" name="${e(name)}" maxlength="${max}" ${required?'required':''} placeholder="${e(placeholder)}">${e(value)}</textarea>`:`<input id="f-${e(name)}" name="${e(name)}" type="${type}" value="${e(value)}" ${required?'required':''} ${readonly?'readonly':''} maxlength="${max}" ${type==='number'?'min="0" step="any"':''} placeholder="${e(placeholder)}">`}</div>`}
const selectField=(name,label,items,value,wide=false)=>`<div class="field ${wide?'wide':''}"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${items.map(([k,v])=>`<option value="${e(k)}" ${k===value?'selected':''}>${e(v)}</option>`).join('')}</select></div>`;
function inquiryForm(kind='acquisition',subject=''){return `<form id="inquiry-form" class="formbox" data-submission="${uid()}">${demo?notice(tr('Preview only. This enquiry will be saved in this browser, not sent to the artist, Telegram or email. Use fictional contact details when testing.','Только демонстрация. Заявка сохранится в этом браузере, но не отправится художнику, в Telegram или на email. Для теста используйте вымышленные контакты.'),'warning'):!flags.inquiriesEnabled?notice(tr('Enquiries are not enabled yet. Contact the studio using the published contact details, if available.','Приём заявок пока не подключён. Используйте опубликованные контакты студии, если они доступны.'),'warning'):''}<div class="error" hidden role="alert"></div><div class="fields">${selectField('kind',tr('I am interested in','Меня интересует'),[['acquisition',tr('Acquiring a work','Приобретение работы')],['commission',tr('A custom project','Индивидуальная работа')],['collaboration',tr('A collaboration','Сотрудничество')]],kind,true)}${field('name',tr('Your name','Ваше имя'),'',{required:true,max:100,placeholder:tr('Your full name','Ваше имя')})}${field('email','Email','',{required:true,type:'email',max:254,placeholder:'you@example.com'})}${field('telegram',tr('Telegram (optional)','Telegram (необязательно)'),'',{max:33,placeholder:'@username'})}${field('city',tr('City / country (optional)','Город / страна (необязательно)'),'',{max:160,placeholder:tr('Your delivery destination','Куда доставить работу')})}${field('message',tr('Your message','Сообщение'),subject?tr('I would like to discuss: ','Хочу обсудить: ')+subject:'',{type:'textarea',wide:true,max:3000,placeholder:tr('Tell us about the work, your space or your idea.','Расскажите о работе, пространстве или идее.')})}</div><div class="hp" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="check"><input type="checkbox" name="consent" required><span>${tr('I agree to the processing of my details to respond to this enquiry.','Я согласен на обработку указанных данных для ответа на этот запрос.')} ${link('/privacy',tr('Privacy notice','Условия обработки данных'))}</span></label><button class="btn full" type="submit" ${!demo&&!flags.inquiriesEnabled?'disabled':''}>${demo?tr('Create a demo enquiry','Создать демо-заявку'):tr('Send enquiry','Отправить запрос')}${icon('arrow')}</button><p class="small muted" style="margin-top:16px">${tr('No online payment. No subscription. Just a conversation about art.','Без онлайн-оплаты и подписок. Только диалог об искусстве.')}</p></form>`}
function contact(params){const s=data.settings;return `<main id="main" class="wrap"><div class="page-head"><p class="eyebrow">ACQUISITIONS / PROJECTS / COLLABORATIONS</p><h1>${tr('Start a conversation.','Начнём с разговора.')}</h1></div><div class="contact-grid"><div class="contact-intro"><h2>${tr('A work. A space.<br>A new possibility.','Работа. Пространство.<br>Новая возможность.')}</h2><p>${tr('Interested in an artwork or have a project in mind? Leave a few details so the studio can understand what you are looking for.','Интересует работа или есть идея проекта? Оставьте несколько деталей, чтобы студия могла понять ваш запрос.')}</p><div class="contact-links">${s.email?`<a class="textlink" href="mailto:${e(s.email)}">${e(s.email)} ${icon('arrow')}</a>`:''}${s.telegram?`<a class="textlink" href="${e(safeExternal(s.telegram))}" target="_blank" rel="noopener noreferrer">Telegram ${icon('arrow')}</a>`:''}${s.instagram?`<a class="textlink" href="${e(safeExternal(s.instagram))}" target="_blank" rel="noopener noreferrer">Instagram ${icon('arrow')}</a>`:''}</div><div class="gallery-note"><p class="eyebrow">${tr('GALLERY REPRESENTATION','ГАЛЕРЕЯ')}</p><p>Artevistas Gallery · Barcelona</p><a class="textlink" href="${e(s.source)}" target="_blank" rel="noopener noreferrer">${tr('View the gallery profile','Открыть профиль в галерее')} ${icon('arrow')}</a></div></div>${inquiryForm('commission',params.get('subject')||'')}</div></main>`}
function checkout(){const ps=activeSaved();return `<main id="main" class="wrap"><div class="page-head"><p class="eyebrow">${tr('YOUR ART SELECTION','ВАШ ВЫБОР')}</p><h1>${tr('Make it yours.','Пусть станет вашим.')}</h1><p>${tr('Your chosen works, one personal enquiry. This is not a checkout or a payment.','Выбранные работы — в одном личном запросе. Это не онлайн-оплата.')}</p></div>${!ps.length?`<div class="catalogue">${empty(tr('Your selection is empty.','Вы пока ничего не выбрали.'),tr('Explore the collection and add a work you would like to ask about.','Откройте коллекцию и добавьте работу, о которой хотите узнать подробнее.'),link('/works',tr('Explore the collection','Открыть коллекцию')+icon('arrow'),'btn'))}</div>`:`<div class="checkout"><div class="checkout-summary"><h2>${tr('Selected works','Выбранные работы')}<sup class="num">${ps.length}</sup></h2>${ps.map(p=>`<div class="inquiry-item">${media(p.images[0],p.title,{cls:'mini'})}<div><h3>${link('/work/'+p.id,e(p.title))}</h3><p>${cat(p.category)} · ${e(money(p.price))}</p>${['sold','reserved'].includes(p.availability)?`<p class="error">${e(labels[p.availability]())}</p>`:''}</div><button class="icon" data-action="remove" data-id="${e(p.id)}" aria-label="${e(tr('Remove ','Убрать ')+p.title)}">${icon('close')}</button></div>`).join('')}<p class="order-note">${tr('Prices are indicative catalogue prices in EUR. Availability, shipping and final terms are confirmed before payment.','Цены указаны в EUR по каталогу. Наличие, доставка и окончательные условия согласуются до оплаты.')}</p></div>${inquiryForm()}</div>`}</main>`}
function privacy(){const p=flags.privacy||{};return `<main id="main" class="legal"><p class="eyebrow">MARK ROX / PRIVACY</p><h1 style="margin-top:20px">${tr('Your details. Your choice.','Ваши данные. Ваш выбор.')}</h1>${demo||!p.controller?notice(tr('Preview privacy notice. The site owner must add their legal identity, contact and actual retention policy before accepting real enquiries.','Демонстрационная политика. До приёма реальных заявок владелец должен указать своё юридическое имя, контакт и фактический срок хранения данных.'),'warning'):''}<h2>${tr('Who handles the data?','Кто обрабатывает данные?')}</h2><p>${p.controller?e(p.controller):tr('The site operator will be identified before launch.','Оператор будет указан перед запуском.')} ${p.contact?`<a href="mailto:${e(p.contact)}">${e(p.contact)}</a>`:''}</p><h2>${tr('What is collected?','Какие данные собираются?')}</h2><p>${tr('When you submit an enquiry, the name, email, optional Telegram username and city, selected artworks and message you provide are stored so the studio can reply. Consent and the enquiry time are recorded. There is no payment-card collection.','При отправке заявки сохраняются имя, email, необязательные Telegram и город, выбранные работы и сообщение — для ответа студии. Также фиксируются согласие и время заявки. Данные банковской карты не собираются.')}</p><h2>${tr('Where does an enquiry go?','Куда поступает заявка?')}</h2><p>${demo?tr('In this preview, only to local browser storage. No email or Telegram message is sent. Do not enter real sensitive information.','В этой демоверсии — только в локальное хранилище браузера. Сообщения в email и Telegram не отправляются. Не вводите чувствительные данные.'):tr('Enquiries are stored in the private studio inbox. ','Заявки сохраняются в закрытой админ-панели. ')+(flags.channels.includes('telegram')?tr('A copy is sent to the configured Telegram account. ','Копия передаётся в настроенный Telegram. '):'')+(flags.channels.includes('email')?tr('A copy is sent by email using Resend. ','Копия отправляется по электронной почте через Resend. '):'')}</p><h2>${tr('Retention and your rights','Хранение и ваши права')}</h2><p>${tr('The configured retention period is ','Установленный срок хранения: ')}${e(p.retention||180)} ${tr('days. You may request access, correction or deletion by contacting the operator. The operator must also remove copies from email, Telegram and backups where applicable.','дней. Для доступа, исправления или удаления данных свяжитесь с оператором. Оператор также должен удалить копии из почты, Telegram и резервных копий, когда это требуется.')}</p><h2>${tr('Browser storage & third parties','Хранилище браузера и внешние сервисы')}</h2><p>${tr('Your language and artwork selection are kept in local browser storage. Studio sign-in uses an essential, secure session cookie on the admin subdomain. There are no advertising trackers. Until photographs are copied to the site, they load from Artevistas, which receives normal image-request connection data such as your IP address.','Язык и список выбранных работ сохраняются локально в браузере. Вход в студию использует необходимый защищённый cookie на поддомене админки. Рекламных трекеров нет. До переноса фотографий на сайт они загружаются из Artevistas; сервис получает технические данные запроса, например IP-адрес.')}</p><div class="actions" style="margin-top:32px"><button class="btn secondary" data-action="clear-local">${tr('Clear my local selection','Очистить мой локальный выбор')}</button>${link('/works',tr('Back to the collection','К коллекции'),'textlink')}</div></main>`}
function success(){return `<main id="main" class="success"><div class="success-icon">${icon('check')}</div><p class="eyebrow">${e(lastSuccess?.reference||'')}</p><h1 style="margin-top:20px">${demo?tr('Demo enquiry saved.','Демо-заявка создана.'):tr('Thank you.<br>Enquiry received.','Спасибо.<br>Запрос получен.')}</h1><p>${demo?tr('Saved in this browser only. No message was sent and no payment was taken. In the admin preview, open Enquiries to review it.','Сохранено только в этом браузере. Сообщение не отправлено, оплата не списана. В демо-админке заявка появится в разделе «Заявки».'):tr('Your enquiry is safely recorded in the studio inbox. Availability, price and shipping will be agreed before payment. Keep the reference above for follow-up.','Заявка сохранена в студии. Наличие, стоимость и доставка будут согласованы до оплаты. Сохраните номер запроса для дальнейшей переписки.')}</p><div class="actions">${link('/works',tr('Keep exploring','Смотреть дальше')+icon('arrow'),'btn')}${adminEntry?link('/admin?tab=inquiries',tr('Back to the studio','Вернуться в студию'),'textlink'):''}</div></main>`}
const notFound=()=>`<main id="main" class="wrap section">${empty(tr('This page is not here.','Этой страницы нет.'),tr('The work may have moved or been unpublished.','Возможно, работа перемещена или снята с публикации.'),link('/works',tr('Back to the works','К работам'),'btn'))}</main>`;
function login(){return `<main id="main" class="login"><section class="login-art"><div class="brand">MARK ROX<i></i></div><h1>${tr('Behind\nthe work.','За\nкулисами.')}</h1><p class="eyebrow">ADMINPRO / PRIVATE STUDIO</p></section><section class="login-panel"><div class="login-card"><p class="eyebrow" style="margin-bottom:20px">ADMINPRO</p><h2>${tr('Studio sign in.','Вход в студию.')}</h2><p>${tr('Your collection, your stories and every conversation in one place.','Ваша коллекция, истории и все заявки — в одном месте.')}</p>${demo?notice(tr('Local admin preview — not a protected account. Real username/password authentication and changes are available in the included server version.','Локальный просмотр админки — не защищённый аккаунт. Настоящий вход и смена логина/пароля доступны в серверной версии.'),'warning'):''}<form id="login-form"><div class="error" role="alert" hidden></div>${field('username',tr('Username','Логин'),'',{required:!demo,placeholder:'admin',max:80})}${field('password',tr('Password','Пароль'),'',{type:'password',required:!demo,max:256,placeholder:'••••••••••••'})}<button class="btn full" type="submit">${demo?tr('Open local admin preview','Открыть демо-админку'):tr('Sign in securely','Войти')}${icon('arrow')}</button></form><button class="textlink" data-action="language">${lang==='en'?'Русский':'English'}</button></div></section></main>`}
const adminTabs=()=>[['catalogue','grid',tr('Catalogue','Каталог')],['inquiries','mail',tr('Enquiries','Заявки')],['artist','user',tr('Artist & site','Художник и сайт')],['integrations','settings',tr('Connections','Подключения')],['account','lock',tr('Account','Аккаунт')]];
function adminShell(tab){return `<div class="admin"><aside class="aside"><div><div class="brand">MARK ROX<i></i></div><p class="eyebrow">ADMINPRO / STUDIO</p></div><nav class="admin-nav">${adminTabs().map(([v,i,t])=>link('/admin?tab='+v,icon(i)+t,tab===v?'active':'')).join('')}</nav><div class="aside-bottom">${demo?link('/',tr('View website','Открыть сайт')+icon('arrow')):`<a href="${e(flags.publicUrl)}" target="_blank" rel="noopener noreferrer">${tr('View website','Открыть сайт')}${icon('arrow')}</a>`}<p class="small muted" style="margin-top:16px">${demo?tr('Local preview','Локальная демоверсия'):tr('Private access','Закрытый доступ')}</p></div></aside><main id="main" class="admin-main"><div class="admin-top"><span>Studio / ${e(adminTabs().find(x=>x[0]===tab)?.[2]||'')}</span><div class="actions">${demo?link('/',icon('arrow')+`<span>${tr('View website','Открыть сайт')}</span>`,'admin-site-link'):`<a class="admin-site-link" href="${e(flags.publicUrl)}" target="_blank" rel="noopener noreferrer" aria-label="${tr('View website','Открыть сайт')}">${icon('arrow')}</a>`}<button class="lang" data-action="language">${lang.toUpperCase()} / ${lang==='en'?'RU':'EN'}</button><button class="textlink" data-action="logout">${tr('Sign out','Выйти')}</button></div></div>${demo?notice(tr('Local preview · Changes live in this browser only. No public site is modified. Use “View website” in this preview to see your changes. No notifications are sent.','Локальная демоверсия · Изменения хранятся в этом браузере. Публичный сайт не меняется. Нажмите «Открыть сайт» в этой демоверсии, чтобы увидеть изменения. Уведомления не отправляются.'),'warning'):''}${tab==='catalogue'?adminCatalogue():tab==='inquiries'?adminInquiries():tab==='artist'?adminSettings():tab==='account'?adminAccount():adminIntegrations()}</main></div>`}
function adminCatalogue(){const ps=data.products.filter(p=>[p.title,p.sku,...(p.tags||[])].join(' ').toLowerCase().includes(adminSearch.toLowerCase()));return `<div class="admin-heading"><div><h1>${tr('Your collection.','Ваша коллекция.')}</h1><p>${tr('Photographs, details and the stories behind every work.','Фотографии, детали и истории каждой работы.')}</p></div><button class="btn" data-action="new-product">${icon('plus')}${tr('Add artwork','Добавить работу')}</button></div><div class="stats">${[[data.products.length,tr('Total works','Всего работ')],[data.products.filter(p=>p.published).length,tr('Published','Опубликовано')],[data.products.filter(p=>p.availability==='sold').length,tr('Sold / archive','Продано / архив')]].map(([n,l])=>`<div class="stat"><p class="small">${l}</p><p class="value">${String(n).padStart(2,'0')}</p></div>`).join('')}</div><div class="admin-toolbar"><label><span class="sr">${tr('Search catalogue','Поиск по каталогу')}</span><input id="admin-search" type="search" value="${e(adminSearch)}" placeholder="${tr('Search title, SKU or tag…','Название, артикул или тег…')}"></label><button class="textlink" data-action="export">${tr('Export catalogue','Экспорт каталога')}${icon('export')}</button></div>${ps.length?`<div class="table-wrap"><table class="admin-table"><thead><tr><th>${tr('Artwork','Работа')}</th><th>${tr('Price','Цена')}</th><th>${tr('Availability','Наличие')}</th><th class="optional">${tr('Visibility','Публикация')}</th><th><span class="sr">${tr('Actions','Действия')}</span></th></tr></thead><tbody>${ps.map(p=>`<tr><td><div class="title-cell">${media(p.images[0],p.title,{cls:'mini'})}<div><strong>${e(p.title)}</strong><p class="small">${cat(p.category)} · ${p.images.length} ${tr('photos','фото')}</p></div></div></td><td>${p.availability==='sold'?'—':e(money(p.price))}</td><td><span class="chip ${p.availability}">${e(labels[p.availability]?.())}</span></td><td class="optional"><span class="chip ${p.published?'':'draft'}">${p.published?tr('Published','Публично'):tr('Draft','Черновик')}</span></td><td><div class="row-actions"><button class="icon" data-action="edit-product" data-id="${e(p.id)}" aria-label="${e(tr('Edit ','Изменить ')+p.title)}">${icon('edit')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty(tr('No artworks yet.','Работ пока нет.'),tr('Add a work or change your search.','Добавьте работу или измените запрос.'))}`}
function adminInquiries(){const qs=data.inquiries||[],statusLabel=s=>({new:tr('New','Новая'),in_progress:tr('In conversation','В работе'),closed:tr('Closed','Закрыта')}[s]||s);return `<div class="admin-heading"><div><h1>${tr('Conversations.','Заявки и разговоры.')}</h1><p>${tr('Every enquiry is saved here, independently of notification delivery.','Все заявки сохраняются здесь независимо от отправки уведомлений.')}</p></div><button class="btn secondary" data-action="refresh-admin">${tr('Refresh','Обновить')}</button></div><div class="requests">${qs.length?qs.map(q=>`<article class="panel"><div class="request-head"><div><h3>${e(q.name)}</h3><p class="request-meta">${e(q.reference)} · ${e(new Date(q.createdAt).toLocaleString(lang==='en'?'en-GB':'ru-RU'))}</p></div><span class="chip ${q.status==='new'?'pending':''}">${statusLabel(q.status)}</span></div><p class="request-meta">${e(q.email)}${q.telegram?' · '+e(q.telegram):''}${q.city?' · '+e(q.city):''}</p><div class="request-items">${(q.items||[]).map(p=>`<p>${e(p.title)}${p.price!=null?' — '+e(money(p.price)):''}</p>`).join('')||e(q.kind)}</div>${q.message?`<div class="request-message">${e(q.message)}</div>`:''}<p class="delivery">${demo?tr('Local demo · nothing sent','Локальная демоверсия · ничего не отправлено'):(q.deliveries||[]).map(x=>e(x.channel)+': '+e({sent:tr('delivered','доставлено'),pending:tr('queued','в очереди'),failed:tr('failed — retry available','ошибка — можно повторить'),sending:tr('sending','отправляется')}[x.state]||x.state)).join(' · ')||tr('Saved to inbox; notifications not configured.','Сохранено в заявках; уведомления не настроены.')}</p><div class="request-footer"><label><span class="sr">${tr('Enquiry status','Статус заявки')}</span><select data-request-status="${e(q.id)}">${['new','in_progress','closed'].map(s=>`<option value="${s}" ${s===q.status?'selected':''}>${statusLabel(s)}</option>`).join('')}</select></label><div class="actions"><a class="btn secondary" href="mailto:${e(q.email)}?subject=${encodeURIComponent('Mark Rox / '+q.reference)}">${tr('Reply','Ответить')}${icon('arrow')}</a>${!demo&&q.deliveries?.some(x=>x.state==='failed')?`<button class="btn secondary" data-action="retry" data-id="${e(q.id)}">${tr('Retry delivery','Повторить отправку')}</button>`:''}<button class="icon" data-action="delete-request" data-id="${e(q.id)}" aria-label="${tr('Delete enquiry','Удалить заявку')}">${icon('trash')}</button></div></div></article>`).join(''):empty(tr('A little quiet, for now.','Пока здесь тихо.'),tr('New enquiries will appear here. In the preview, open the website from this studio and submit a fictional enquiry.','Новые заявки появятся здесь. Для теста откройте сайт из этой админки и отправьте вымышленную заявку.'))}</div>`}
function adminSettings(){const s=data.settings;return `<div class="admin-heading"><div><h1>${tr('The artist. The story.','Художник и история.')}</h1><p>${tr('English is the default. Russian is one switch away.','По умолчанию — английский. Русский доступен по переключателю.')}</p></div></div><form id="settings-form" class="settings"><div class="error" role="alert" hidden></div><section class="panel"><h2>${tr('Identity & homepage','Имя и главная страница')}</h2><div class="fields">${field('name',tr('Artist name','Имя художника'),s.name,{required:true,wide:true,max:120})}${field('headlineEn','Headline · English',s.headlineEn,{type:'textarea',max:150})}${field('headlineRu','Заголовок · Русский',s.headlineRu,{type:'textarea',max:150})}${field('introEn','Introduction · English',s.introEn,{type:'textarea',max:600})}${field('introRu','Вступление · Русский',s.introRu,{type:'textarea',max:600})}${selectField('heroId',tr('First featured work','Первая работа на главной'),published().map(p=>[p.id,p.title]),s.heroId,true)}</div></section><section class="panel"><h2>${tr('Biography & portrait','Биография и портрет')}</h2><div class="fields">${field('bioEn','Biography · English',s.bioEn,{type:'textarea',wide:true,max:8000})}${field('bioRu','Биография · Русский',s.bioRu,{type:'textarea',wide:true,max:8000})}${field('moreEn','Extended biography · English',s.moreEn,{type:'textarea',wide:true,max:8000})}${field('moreRu','Подробная биография · Русский',s.moreRu,{type:'textarea',wide:true,max:8000})}${field('portrait',tr('Portrait image URL','Ссылка на портрет'),s.portrait,{wide:true,max:4000000})}<div class="field wide"><label for="portrait-upload">${tr('Upload a new portrait','Загрузить новый портрет')}</label><input id="portrait-upload" type="file" accept="image/jpeg,image/png,image/webp"><span class="help">JPG / PNG / WebP · ${tr('up to 12 MB input','исходник до 12 МБ')}</span></div></div></section><section class="panel"><h2>${tr('Public contact details','Публичные контакты')}</h2><div class="fields">${field('email','Email',s.email,{type:'email',wide:true,max:254})}${field('telegram','Telegram URL',s.telegram,{type:'url',max:2048,placeholder:'https://t.me/your_studio'})}${field('instagram','Instagram URL',s.instagram,{type:'url',max:2048,placeholder:'https://instagram.com/your_studio'})}</div><p class="small" style="margin-top:20px">${tr('These details are public. Notification recipients and secrets are configured privately on the server.','Эти контакты видны посетителям. Получатели уведомлений и секретные ключи настраиваются отдельно на сервере.')}</p></section><button class="btn" type="submit">${tr('Save site details','Сохранить данные сайта')}${icon('check')}</button></form>`}
function adminIntegrations(){return `<div class="admin-heading"><div><h1>${tr('Stay connected.','Всегда на связи.')}</h1><p>${tr('A private studio inbox, with Telegram and email notifications.','Закрытая админ-панель с уведомлениями в Telegram и на почту.')}</p></div></div><div class="integration-grid">${[['telegram','send','Telegram',tr('Create a bot with BotFather. Add it to your private chat or group, then configure its token and the recipient chat on the server.','Создайте бота через BotFather. Добавьте его в личный чат или группу, затем укажите токен и чат получателя на сервере.')],['email','mail','Email / Resend',tr('Verify your sender domain in Resend, add its API key and set the sender and recipient addresses on the server.','Подтвердите домен отправителя в Resend, добавьте ключ доступа, email отправителя и email получателя на сервере.')]].map(([id,ic,title,text])=>`<section class="panel"><div class="integration-icon">${icon(ic)}<span class="chip ${flags.channels.includes(id)&&!demo?'':'pending'}">${flags.channels.includes(id)&&!demo?tr('Configured','Настроено'):tr('Not connected','Не подключено')}</span></div><h2>${title}</h2><p>${text}</p><p style="margin-top:16px">${tr('Credentials never appear in the public page or browser storage. See the included launch guide.','Ключи никогда не попадают в публичный сайт или хранилище браузера. Инструкция есть в комплекте.')}</p></section>`).join('')}<section class="panel wide"><h2>${tr('Saved first. Delivered next.','Сначала сохранение. Затем отправка.')}</h2><p>${tr('Every accepted enquiry is saved to the database before notification delivery. Failed notifications retry automatically, with a manual retry in the inbox. Delivery status is visible for each channel.','Каждая принятая заявка сначала сохраняется в базе. Неудачные уведомления повторяются автоматически; также доступен ручной повтор. Статус каждого канала виден в заявке.')}</p><p style="margin-top:16px">${tr('The admin address is separate: adminpro.your-domain. It has no button or link on the public website. Set your real domain and HTTPS before launch.','Админка открывается отдельно: adminpro.ваш-домен. На публичном сайте нет кнопки или ссылки на неё. Перед запуском укажите реальный домен и подключите HTTPS.')}</p></section></div>`}
function adminAccount(){return `<div class="admin-heading"><div><h1>${tr('Private by design.','Только для своих.')}</h1><p>${tr('Change your username and password. All current sessions will be signed out.','Смена логина и пароля завершит все текущие сеансы.')}</p></div></div><form id="account-form" class="formbox settings">${demo?notice(tr('The preview has no real password protection. This form works when the included backend is running.','В демоверсии нет настоящей защиты паролем. Эта форма работает при запуске серверной части.'),'warning'):''}<div class="error" role="alert" hidden></div><div class="fields">${field('oldPassword',tr('Current password','Текущий пароль'),'',{type:'password',required:true,wide:true,max:256})}${field('username',tr('New username','Новый логин'),session?.username||'',{required:true,wide:true,max:80})}${field('newPassword',tr('New password · at least 12 characters','Новый пароль · минимум 12 символов'),'',{type:'password',required:true,max:256})}${field('confirmPassword',tr('Confirm new password','Повторите новый пароль'),'',{type:'password',required:true,max:256})}</div><button class="btn" style="margin-top:24px" type="submit" ${demo?'disabled':''}>${tr('Update credentials','Изменить логин и пароль')}${icon('lock')}</button></form>`}
function render(){const raw=path(),[p,query='']=raw.split('?'),params=new URLSearchParams(query);document.documentElement.lang=lang;document.title=p.startsWith('/admin')?'MARK ROX / AdminPro':'MARK ROX — '+tr('Art outside the orbit','Искусство вне орбиты');if(p==='/admin'){if(!adminEntry&&!demo&&!runtime.dev){$('#app').innerHTML=header()+notFound()+footer()}else $('#app').innerHTML=session?adminShell(params.get('tab')||'catalogue'):login()}else{const content=p==='/'?home():p==='/works'?catalogue(params):p.startsWith('/work/')?productPage(p.slice(6)):p==='/artist'?artist():p==='/contact'?contact(params):p==='/inquiry'?checkout():p==='/privacy'?privacy():p==='/success'&&lastSuccess?success():notFound();$('#app').innerHTML=header()+content+footer()}bindImages();if(p.startsWith('/work/')){const work=published().find(x=>x.id===p.slice(6));if(work)document.title=work.title+' — Mark Rox'}}
function openModal(title,body){const d=$('#dialog');d.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon" data-action="close-modal" aria-label="${tr('Close','Закрыть')}">${icon('close')}</button></div><div class="modal-body">${body}</div>`;d.setAttribute('aria-labelledby','modal-title');if(!d.open)d.showModal();document.body.style.overflow='hidden';bindImages(d)}
function closeModal(){const d=$('#dialog');d.close();document.body.style.overflow=''}
let lightboxProduct=null,lightboxIndex=0;function lightbox(id,index=0){const p=published().find(x=>x.id===id);if(!p)return;lightboxProduct=p;lightboxIndex=(index+p.images.length)%p.images.length;openModal(e(p.title),`<div class="lightbox-stage"><button class="icon" data-action="lightbox-prev" aria-label="${tr('Previous photo','Предыдущее фото')}">${icon('left')}</button><div data-action="zoom" tabindex="0" role="button" aria-label="${tr('Toggle zoom','Увеличить или уменьшить')}">${media(p.images[lightboxIndex],p.title+' — '+(lightboxIndex+1),{eager:true})}</div><button class="icon" data-action="lightbox-next" aria-label="${tr('Next photo','Следующее фото')}">${icon('right')}</button></div><div class="lightbox-foot"><span aria-live="polite">${String(lightboxIndex+1).padStart(2,'0')} / ${String(p.images.length).padStart(2,'0')}</span><button data-action="zoom">${tr('Zoom 1× / 1.8×','Масштаб 1× / 1,8×')}</button><a href="${e(asset(safeImage(p.images[lightboxIndex])))}" target="_blank" rel="noopener noreferrer">${tr('Open original ↗','Открыть оригинал ↗')}</a></div>`)}
function editorImages(){return `<div class="upload-list">${editor.images.map((u,i)=>`<div class="upload-tile">${media(u,String(i+1),{cls:'mini'})}<button class="icon" type="button" data-action="remove-editor-image" data-index="${i}" aria-label="${tr('Remove image','Удалить фото')} ${i+1}">${icon('close')}</button><button class="cover-btn" type="button" data-action="cover-image" data-index="${i}">${i===0?tr('Cover','Обложка'):tr('Make cover','На обложку')}</button></div>`).join('')}</div>`}
function productEditor(id){const current=data.products.find(p=>p.id===id);editing=!!current;editor=current?structuredClone(current):{id:'work-'+Date.now().toString(36),title:'',category:'sculpture',availability:'on_request',price:null,year:new Date().getFullYear(),dimensions:'',mediumEn:'',mediumRu:'',descriptionEn:'',descriptionRu:'',images:[],tags:[],sku:'',sourceUrl:'',published:true,featured:false,version:0};const p=editor;openModal(tr(editing?'Edit artwork':'Add artwork',editing?'Редактировать работу':'Добавить работу'),`<form id="product-form"><div class="error" role="alert" hidden></div><div class="fields">${field('title',tr('Artwork title','Название работы'),p.title,{required:true,wide:true,max:150})}${field('id',tr('URL slug','Адрес карточки'),p.id,{required:true,readonly:editing,max:100})}${selectField('category',tr('Category','Категория'),[['sculpture',cat('sculpture')],['painting',cat('painting')],['other',cat('other')]],p.category)}${field('price',tr('Price · EUR (blank = on request)','Цена · EUR (пусто = по запросу)'),p.price??'',{type:'number'})}${selectField('availability',tr('Availability','Наличие'),Object.keys(labels).map(k=>[k,labels[k]()]),p.availability)}${field('year',tr('Year','Год'),p.year??'',{type:'number'})}${field('dimensions',tr('Dimensions','Размеры'),p.dimensions,{max:150})}${field('sku',tr('SKU / reference','Артикул'),p.sku,{max:100})}${field('tags',tr('Tags · comma-separated','Теги · через запятую'),(p.tags||[]).join(', '),{max:600,placeholder:'ARTonaut, Sculpture, Mixed media'})}<div class="field wide"><label for="artwork-upload">${tr('Photographs · up to 8','Фотографии · до 8')}</label><div class="upload-area">${tr('The first photo is the card cover. Upload JPG, PNG or WebP. Original input up to 12 MB; images are resized to 1800 px.','Первое фото — обложка карточки. Загружайте JPG, PNG или WebP. Исходник до 12 МБ; фото уменьшается до 1800 px.')}<input id="artwork-upload" type="file" accept="image/jpeg,image/png,image/webp" multiple></div><div id="editor-images">${editorImages()}</div><div class="help" id="upload-status" aria-live="polite"></div></div>${field('mediumEn','Medium · English',p.mediumEn,{max:300,wide:true})}${field('descriptionEn','Description · English',p.descriptionEn,{type:'textarea',wide:true,max:6000})}<details class="details-lang"><summary>Русская версия / Russian translation</summary><div class="fields">${field('mediumRu','Материал · Русский',p.mediumRu,{wide:true,max:300})}${field('descriptionRu','Описание · Русский',p.descriptionRu,{type:'textarea',wide:true,max:6000})}</div></details>${field('sourceUrl',tr('Source URL (optional)','Источник (необязательно)'),p.sourceUrl,{type:'url',wide:true,max:2048})}<label class="check inline"><input type="checkbox" name="published" ${p.published?'checked':''}>${tr('Publish in catalogue','Опубликовать в каталоге')}</label><label class="check inline"><input type="checkbox" name="featured" ${p.featured?'checked':''}>${tr('Feature on homepage','Показывать на главной')}</label></div><div class="modal-actions">${editing?`<button class="btn danger" type="button" data-action="delete-product" data-id="${e(p.id)}">${icon('trash')}${tr('Delete','Удалить')}</button>`:`<button class="btn secondary" type="button" data-action="close-modal">${tr('Cancel','Отмена')}</button>`}<button class="btn" type="submit">${tr('Save artwork','Сохранить работу')}${icon('check')}</button></div></form>`)}
async function fileImage(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12*1024*1024)throw Error(tr('Use JPG, PNG or WebP up to 12 MB.','Используйте JPG, PNG или WebP до 12 МБ.'));const bitmap=await createImageBitmap(file);const scale=Math.min(1,1800/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return canvas.toDataURL('image/webp',.88)}
function showError(form,error){const box=$('.error',form);if(box){box.textContent=error.message||String(error);box.hidden=false;box.scrollIntoView({block:'nearest',behavior:'smooth'})}else toast(error.message||String(error))}
function selection(id,removeOnly=false){if(saved.includes(id)||removeOnly)saved=saved.filter(x=>x!==id);else{const p=published().find(x=>x.id===id);if(!p||['sold','reserved'].includes(p.availability))return;if(saved.length>=20){toast(tr('Select up to 20 works.','Можно выбрать до 20 работ.'));return}saved.push(id)}try{put('mr-selection',saved)}catch(err){toast(err.message)}render()}
async function refreshAdmin(){if(!demo){const result=await api('/api/admin/state');data={...data,...result};flags={...flags,...result.flags}}render()}
function exportJson(name,value){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',async ev=>{const route=ev.target.closest('a[data-route]');if(route&&!ev.ctrlKey&&!ev.metaKey&&!ev.shiftKey&&!ev.altKey){ev.preventDefault();const href=route.getAttribute('href');if($('#dialog').open)closeModal();if(href.includes('/works')){const u=href.replace(/^#/,'');if(!u.includes('?')){filter='all';tagFilter='';search=''}}go(href.replace(/^#/,''));return}const el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;try{if(a==='language'){lang=lang==='en'?'ru':'en';try{put('mr-language',lang)}catch{}if($('#dialog').open)closeModal();render()}else if(a==='menu'){menu=!menu;render()}else if(a==='hero-next'){heroIndex++;render()}else if(a==='save'||a==='remove'){selection(id,a==='remove');toast(tr(a==='remove'?'Removed from selection.':'Selection updated.',a==='remove'?'Убрано из списка.':'Список обновлён.'))}else if(a==='enquire'){if(!saved.includes(id)){selection(id)}go('/inquiry')}else if(a==='filter'){filter=el.dataset.filter;tagFilter='';const p='/works';if(demo)history.replaceState({},'','#'+p);else history.replaceState({},'',p);render()}else if(a==='tag'){tagFilter=tagFilter===el.dataset.tag?'':el.dataset.tag;render()}else if(a==='clear-filters'){filter='all';tagFilter='';search='';go('/works')}else if(a==='lightbox'){lightbox(id,Number(el.dataset.index||0))}else if(a==='thumbnail'){const p=published().find(x=>x.id===id),i=Number(el.dataset.index);$('.main-photo').innerHTML=media(p.images[i],p.title+' — '+(i+1),{eager:true,sold:p.availability==='sold'});$('.main-photo').dataset.index=i;$$('.thumb').forEach(x=>{x.classList.toggle('active',Number(x.dataset.index)===i);x.setAttribute('aria-pressed',String(Number(x.dataset.index)===i))});bindImages()}else if(a==='close-modal'){closeModal()}else if(a==='lightbox-prev'){lightbox(lightboxProduct.id,lightboxIndex-1)}else if(a==='lightbox-next'){lightbox(lightboxProduct.id,lightboxIndex+1)}else if(a==='zoom'){$('.lightbox-stage .media')?.classList.toggle('zoomed')}else if(a==='new-product'){productEditor()}else if(a==='edit-product'){productEditor(id)}else if(a==='remove-editor-image'){editor.images.splice(Number(el.dataset.index),1);$('#editor-images').innerHTML=editorImages();bindImages($('#dialog'))}else if(a==='cover-image'){const i=Number(el.dataset.index),[img]=editor.images.splice(i,1);editor.images.unshift(img);$('#editor-images').innerHTML=editorImages();bindImages($('#dialog'))}else if(a==='delete-product'){if(!confirm(tr('Delete this artwork? This removes it from the catalogue.','Удалить работу? Она исчезнет из каталога.')))return;await api('/api/admin/products/'+id,'DELETE');if(demo){}else data.products=data.products.filter(x=>x.id!==id);closeModal();render();toast(tr('Artwork deleted.','Работа удалена.'))}else if(a==='logout'){if(!demo)await api('/api/admin/logout','POST',{});session=null;render()}else if(a==='export'){exportJson('mark-rox-catalogue.json',{products:data.products,settings:data.settings})}else if(a==='refresh-admin'){await refreshAdmin()}else if(a==='delete-request'){if(!confirm(tr('Permanently delete this enquiry and its contact details? External email/Telegram copies must be removed separately.','Навсегда удалить заявку и контакты? Копии в почте/Telegram нужно удалить отдельно.')))return;await api('/api/admin/inquiries/'+id,'DELETE');await refreshAdmin()}else if(a==='retry'){await api('/api/admin/inquiries/'+id+'/retry','POST',{});await refreshAdmin();toast(tr('Delivery queued again.','Отправка снова поставлена в очередь.'))}else if(a==='clear-local'){saved=[];try{put('mr-selection',[])}catch{}toast(tr('Your selection is cleared.','Ваш выбор очищен.'));render()}}catch(err){if($('#dialog').open)showError($('#dialog'),err);else toast(err.message)}});
let searchTimer;document.addEventListener('input',ev=>{if(ev.target.id==='catalogue-search'||ev.target.id==='admin-search'){clearTimeout(searchTimer);const target=ev.target.id;searchTimer=setTimeout(()=>{const value=ev.target.value,position=ev.target.selectionStart;if(target==='catalogue-search')search=value;else adminSearch=value;render();const el=$('#'+target);el?.focus();try{el.setSelectionRange(position,position)}catch{}},180)}});
document.addEventListener('change',async ev=>{const el=ev.target;try{if(el.id==='catalogue-sort'){sort=el.value;render()}else if(el.dataset.requestStatus){await api('/api/admin/inquiries/'+el.dataset.requestStatus,'PATCH',{status:el.value});await refreshAdmin()}else if(el.id==='artwork-upload'){const files=[...el.files];if(editor.images.length+files.length>8)throw Error(tr('Maximum 8 photos per artwork.','Максимум 8 фото на работу.'));const form=$('#product-form'),submit=$('button[type="submit"]',form);submit.disabled=true;$('#upload-status').textContent=tr('Processing photographs…','Обрабатываем фотографии…');try{for(const f of files){const image=await fileImage(f);const result=await api('/api/admin/upload','POST',{image});editor.images.push(result.url)}$('#editor-images').innerHTML=editorImages();bindImages($('#dialog'));$('#upload-status').textContent=tr('Photos ready. Save the artwork to publish.','Фото готовы. Сохраните карточку для публикации.')}finally{submit.disabled=false;el.value=''}}else if(el.id==='portrait-upload'){el.disabled=true;try{const result=await api('/api/admin/upload','POST',{image:await fileImage(el.files[0])});$('#f-portrait').value=result.url;toast(tr('Portrait ready. Save site details.','Портрет готов. Сохраните данные сайта.'))}finally{el.disabled=false;el.value=''}}}catch(err){if(el.closest('form'))showError(el.closest('form'),err);else toast(err.message)}});
document.addEventListener('submit',async ev=>{const form=ev.target;if(!['login-form','inquiry-form','product-form','settings-form','account-form'].includes(form.id))return;ev.preventDefault();const error=$('.error',form);if(error)error.hidden=true;const submit=$('button[type="submit"]',form);if(submit.disabled)return;submit.disabled=true;const fd=new FormData(form),body=Object.fromEntries(fd);try{if(form.id==='login-form'){if(demo){session={username:'Preview',csrf:''}}else session=await api('/api/admin/login','POST',{username:body.username,password:body.password});if(!demo){const result=await api('/api/admin/state');data={...data,...result};flags={...flags,...result.flags}}go('/admin')}else if(form.id==='inquiry-form'){if(requestBusy)return;requestBusy=true;try{if(body.telegram&&!/^@[a-zA-Z0-9_]{5,32}$/.test(body.telegram))throw Error(tr('Telegram should be @username (5–32 letters, numbers or underscores).','Telegram должен быть @username (5–32 буквы, цифры или подчёркивания).'));if(body.name.trim().length<2)throw Error(tr('Please enter your name.','Введите имя.'));const productIds=activeSaved().map(x=>x.id);if(body.kind==='acquisition'&&!productIds.length)throw Error(tr('Please select a work first, or choose a project enquiry.','Сначала выберите работу или измените тип запроса на проект.'));lastSuccess=await api('/api/inquiries','POST',{...body,name:body.name.trim(),consent:fd.has('consent'),productIds,lang,submissionId:form.dataset.submission});saved=[];try{put('mr-selection',[])}catch{}go('/success')}finally{requestBusy=false}}else if(form.id==='product-form'){if(!editor.images.length)throw Error(tr('Add at least one photo.','Добавьте хотя бы одну фотографию.'));if(!/^[a-z0-9][a-z0-9-]{1,99}$/.test(body.id))throw Error(tr('URL slug: 2–100 lowercase letters, numbers and hyphens.','Адрес: 2–100 строчных латинских букв, цифр и дефисов.'));const price=body.price===''?null:Number(body.price),year=body.year===''?null:Number(body.year);if(price!==null&&(!Number.isFinite(price)||price<0))throw Error(tr('Check the price.','Проверьте цену.'));if(year!==null&&(!Number.isInteger(year)||year<1900||year>2100))throw Error(tr('Check the year.','Проверьте год.'));const p={...editor,...body,price,year,images:editor.images,tags:[...new Set(body.tags.split(',').map(x=>x.trim()).filter(Boolean))],published:fd.has('published'),featured:fd.has('featured')};await api('/api/admin/products'+(editing?'/'+editor.id:''),editing?'PUT':'POST',p);if(!demo){const result=await api('/api/admin/state');data={...data,...result}}closeModal();render();toast(tr('Artwork saved.','Работа сохранена.'))}else if(form.id==='settings-form'){await api('/api/admin/settings','PUT',body);if(!demo){const result=await api('/api/admin/state');data={...data,...result}}render();toast(tr('Site details saved.','Данные сайта сохранены.'))}else if(form.id==='account-form'){if(body.newPassword!==body.confirmPassword)throw Error(tr('Passwords do not match.','Пароли не совпадают.'));if(body.newPassword.length<12)throw Error(tr('Use at least 12 characters.','Используйте минимум 12 символов.'));await api('/api/admin/account','PUT',body);session=null;render();toast(tr('Credentials changed. Please sign in again.','Данные изменены. Войдите заново.'))}}catch(err){showError(form,err)}finally{submit.disabled=false}});
$('#dialog').addEventListener('close',()=>{document.body.style.overflow=''});$('#dialog').addEventListener('click',ev=>{if(ev.target.id==='dialog'){const r=ev.target.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)closeModal()}});
document.addEventListener('keydown',ev=>{if($('#dialog').open&&$('.lightbox-stage')){if(ev.key==='ArrowLeft'){ev.preventDefault();lightbox(lightboxProduct.id,lightboxIndex-1)}if(ev.key==='ArrowRight'){ev.preventDefault();lightbox(lightboxProduct.id,lightboxIndex+1)}if((ev.key==='Enter'||ev.key===' ')&&ev.target.dataset.action==='zoom'){ev.preventDefault();$('.lightbox-stage .media')?.classList.toggle('zoomed')}}});
window.addEventListener('hashchange',()=>{menu=false;render();window.scrollTo(0,0)});window.addEventListener('popstate',()=>{menu=false;render()});
async function init(){if(!demo){try{const result=await api('/api/catalog');data={...data,...result};flags={...flags,...result.flags};if(adminEntry||runtime.dev&&location.pathname==='/admin'){const auth=await api('/api/admin/session');if(auth.authenticated){session=auth;const a=await api('/api/admin/state');data={...data,...a};flags={...flags,...a.flags}}}}catch(err){loadError=tr('Live service is unavailable. The reference catalogue is shown read-only. Enquiries and editing are unavailable.','Сервер недоступен. Показан справочный каталог без возможности отправлять заявки и редактировать.');flags.inquiriesEnabled=false}}if(adminEntry&&!demo&&location.pathname==='/'){history.replaceState({},'','/admin')}render();window.MARKROX_READY=true}
init();
})();
